// AddressMode Texture reference addressing modes
type AddressMode int32

const (
	TrAddressModeWrap   AddressMode = 0 // Wrapping address mode
	TrAddressModeClamp  AddressMode = 1 // Clamp to edge address mode
	TrAddressModeMirror AddressMode = 2 // Mirror address mode
	TrAddressModeBorder AddressMode = 3 // Border address mode
)

func (e AddressMode) String() string {
	switch e {
	case TrAddressModeWrap:
		return "TrAddressModeWrap"
	case TrAddressModeClamp:
		return "TrAddressModeClamp"
	case TrAddressModeMirror:
		return "TrAddressModeMirror"
	case TrAddressModeBorder:
		return "TrAddressModeBorder"
	}
	return fmt.Sprintf("AddressMode(%d)", e)
}

// FilterMode Texture reference filtering modes
type FilterMode int32

const (
	TrFilterModePoint  FilterMode = 0 // Point filter mode
	TrFilterModeLinear FilterMode = 1 // Linear filter mode
)

func (e FilterMode) String() string {
	switch e {
	case TrFilterModePoint:
		return "TrFilterModePoint"
	case TrFilterModeLinear:
		return "TrFilterModeLinear"
	}
	return fmt.Sprintf("FilterMode(%d)", e)
}

