// PointerAttribute Pointer information
type PointerAttribute int32

const (
	PointerAttributeContext PointerAttribute = 1 // The [Context] on which a pointer was allocated or registered
	// PointerAttributeMemoryType: The [MemoryType] describing the physical location of a pointer
	PointerAttributeMemoryType PointerAttribute = 2
	// PointerAttributeDevicePointer: The address at which a pointer's memory may be accessed on the device
	PointerAttributeDevicePointer PointerAttribute = 3
	// PointerAttributeHostPointer: The address at which a pointer's memory may be accessed on the host
	PointerAttributeHostPointer PointerAttribute = 4
	// PointerAttributePointerAttributeP2PTokens: A pair of tokens for use with the nv-p2p.h Linux kernel interface
	PointerAttributePointerAttributeP2PTokens PointerAttribute = 5
	// PointerAttributeSyncMemops: Synchronize every synchronous memory operation initiated on this region
	PointerAttributeSyncMemops PointerAttribute = 6
	PointerAttributeBufferId   PointerAttribute = 7 // A process-wide unique ID for an allocated memory region
	PointerAttributeIsManaged  PointerAttribute = 8 // Indicates if the pointer points to managed memory
	// PointerAttributeDeviceOrdinal: A device ordinal of a device on which a pointer was allocated or registered
	PointerAttributeDeviceOrdinal PointerAttribute = 9
	// PointerAttributeIsLegacyCudaIpcCapable: 1 if this pointer maps to an allocation that is suitable for cudaIpcGetMemHandle, 0 otherwise *
	PointerAttributeIsLegacyCudaIpcCapable PointerAttribute = 10
	PointerAttributeRangeStartAddr         PointerAttribute = 11 // Starting address for this requested pointer
	PointerAttributeRangeSize              PointerAttribute = 12 // Size of the address range for this requested pointer
	// PointerAttributeMapped: 1 if this pointer is in a valid address range that is mapped to a backing allocation, 0 otherwise *
	PointerAttributeMapped PointerAttribute = 13
	// PointerAttributeAllowedHandleTypes: Bitmask of allowed [MemAllocationHandleType] for this allocation *
	PointerAttributeAllowedHandleTypes PointerAttribute = 14
	// PointerAttributeIsGpuDirectRdmaCapable: 1 if the memory this pointer is referencing can be used with the GPUDirect RDMA API *
	PointerAttributeIsGpuDirectRdmaCapable PointerAttribute = 15
	// PointerAttributePointerAttributeAccessFlags: Returns the access flags the device associated with the current context has on the corresponding memory referenced by the pointer given
	PointerAttributePointerAttributeAccessFlags PointerAttribute = 16
	// PointerAttributeMempoolHandle: Returns the mempool handle for the allocation if it was allocated from a mempool. Otherwise returns NULL. *
	PointerAttributeMempoolHandle PointerAttribute = 17
	// PointerAttributeMappingSize: Size of the actual underlying mapping that the pointer belongs to *
	PointerAttributeMappingSize PointerAttribute = 18
	// PointerAttributeMappingBaseAddr: The start address of the mapping that the pointer belongs to *
	PointerAttributeMappingBaseAddr PointerAttribute = 19
	// PointerAttributeMemoryBlockId: A process-wide unique id corresponding to the physical allocation the pointer belongs to *
	PointerAttributeMemoryBlockId PointerAttribute = 20
	// PointerAttributeIsHwDecompressCapable: Returns in *data a boolean that indicates whether the pointer points to memory that is capable to be used for hardware accelerated decompression.
	PointerAttributeIsHwDecompressCapable PointerAttribute = 21
)

