// FunctionAttribute Function properties
type FunctionAttribute int32

const (
	// FuncAttributeMaxThreadsPerBlock: The maximum number of threads per block, beyond which a launch of the function would fail. This number depends on both the function and the device on which the function is currently loaded.
	FuncAttributeMaxThreadsPerBlock FunctionAttribute = 0
	// FuncAttributeSharedSizeBytes: The size in bytes of statically-allocated shared memory required by this function. This does not include dynamically-allocated shared memory requested by the user at runtime.
	FuncAttributeSharedSizeBytes FunctionAttribute = 1
	// FuncAttributeConstSizeBytes: The size in bytes of user-allocated constant memory required by this function.
	FuncAttributeConstSizeBytes FunctionAttribute = 2
	// FuncAttributeLocalSizeBytes: The size in bytes of local memory used by each thread of this function.
	FuncAttributeLocalSizeBytes FunctionAttribute = 3
	// FuncAttributeNumRegs: The number of registers used by each thread of this function.
	FuncAttributeNumRegs FunctionAttribute = 4
	// FuncAttributePtxVersion: The PTX virtual architecture version for which the function was compiled. This value is the major PTX version * 10 + the minor PTX version, so a PTX version 1.3 function would return the value 13. Note that this may return the undefined value of 0 for cubins compiled prior to CUDA 3.0.
	FuncAttributePtxVersion FunctionAttribute = 5
	// FuncAttributeBinaryVersion: The binary architecture version for which the function was compiled. This value is the major binary version * 10 + the minor binary version, so a binary version 1.3 function would return the value 13. Note that this will return a value of 10 for legacy cubins that do not have a properly-encoded binary architecture version.
	FuncAttributeBinaryVersion FunctionAttribute = 6
	// FuncAttributeCacheModeCa: The attribute to indicate whether the function has been compiled with user specified option "-Xptxas --dlcm=ca" set .
	FuncAttributeCacheModeCa FunctionAttribute = 7
	// FuncAttributeMaxDynamicSharedSizeBytes: The maximum size in bytes of dynamically-allocated shared memory that can be used by this function. If the user-specified dynamic shared memory size is larger than this value, the launch will fail. The default value of this attribute is [DevAttrMaxSharedMemoryPerBlock] - [FuncAttributeSharedSizeBytes], except when [FuncAttributeSharedSizeBytes] is greater than [DevAttrMaxSharedMemoryPerBlock], then the default value of this attribute is 0. The value can be increased to [DevAttrMaxSharedMemoryPerBlockOptin] - [FuncAttributeSharedSizeBytes]. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributeMaxDynamicSharedSizeBytes FunctionAttribute = 8
	// FuncAttributePreferredSharedMemoryCarveout: On devices where the L1 cache and shared memory use the same hardware resources, this sets the shared memory carveout preference, in percent of the total shared memory. Refer to [DevAttrMaxSharedMemoryPerMultiprocessor]. This is only a hint, and the driver can choose a different ratio if required to execute the function. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributePreferredSharedMemoryCarveout FunctionAttribute = 9
	// FuncAttributeClusterSizeMustBeSet: If this attribute is set, the kernel must launch with a valid cluster size specified. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributeClusterSizeMustBeSet FunctionAttribute = 10
	// FuncAttributeRequiredClusterWidth: The required cluster width in blocks. The values must either all be 0 or all be positive. The validity of the cluster dimensions is otherwise checked at launch time. If the value is set during compile time, it cannot be set at runtime. Setting it at runtime will return [ErrNotPermitted]. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributeRequiredClusterWidth FunctionAttribute = 11
	// FuncAttributeRequiredClusterHeight: The required cluster height in blocks. The values must either all be 0 or all be positive. The validity of the cluster dimensions is otherwise checked at launch time. If the value is set during compile time, it cannot be set at runtime. Setting it at runtime should return [ErrNotPermitted]. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributeRequiredClusterHeight FunctionAttribute = 12
	// FuncAttributeRequiredClusterDepth: The required cluster depth in blocks. The values must either all be 0 or all be positive. The validity of the cluster dimensions is otherwise checked at launch time. If the value is set during compile time, it cannot be set at runtime. Setting it at runtime should return [ErrNotPermitted]. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributeRequiredClusterDepth FunctionAttribute = 13
	// FuncAttributeNonPortableClusterSizeAllowed: Whether the function can be launched with non-portable cluster size. 1 is allowed, 0 is disallowed. A non-portable cluster size may only function on the specific SKUs the program is tested on. The launch might fail if the program is run on a different hardware platform. CUDA API provides cudaOccupancyMaxActiveClusters to assist with checking whether the desired size can be launched on the current device. Portable Cluster Size A portable cluster size is guaranteed to be functional on all compute capabilities higher than the target compute capability. The portable cluster size for sm_90 is 8 blocks per cluster. This value may increase for future compute capabilities. The specific hardware unit may support higher cluster sizes that’s not guaranteed to be portable. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributeNonPortableClusterSizeAllowed FunctionAttribute = 14
	// FuncAttributeClusterSchedulingPolicyPreference: The block scheduling policy of a function. The value type is [ClusterSchedulingPolicy] / cudaClusterSchedulingPolicy. See [Function.SetAttribute], [Kernel.SetAttribute]
	FuncAttributeClusterSchedulingPolicyPreference FunctionAttribute = 15
)

func (e FunctionAttribute) String() string {
	switch e {
	case FuncAttributeMaxThreadsPerBlock:
		return "FuncAttributeMaxThreadsPerBlock"
	case FuncAttributeSharedSizeBytes:
		return "FuncAttributeSharedSizeBytes"
	case FuncAttributeConstSizeBytes:
		return "FuncAttributeConstSizeBytes"
	case FuncAttributeLocalSizeBytes:
		return "FuncAttributeLocalSizeBytes"
	case FuncAttributeNumRegs:
		return "FuncAttributeNumRegs"
	case FuncAttributePtxVersion:
		return "FuncAttributePtxVersion"
	case FuncAttributeBinaryVersion:
		return "FuncAttributeBinaryVersion"
	case FuncAttributeCacheModeCa:
		return "FuncAttributeCacheModeCa"
	case FuncAttributeMaxDynamicSharedSizeBytes:
		return "FuncAttributeMaxDynamicSharedSizeBytes"
	case FuncAttributePreferredSharedMemoryCarveout:
		return "FuncAttributePreferredSharedMemoryCarveout"
	case FuncAttributeClusterSizeMustBeSet:
		return "FuncAttributeClusterSizeMustBeSet"
	case FuncAttributeRequiredClusterWidth:
		return "FuncAttributeRequiredClusterWidth"
	case FuncAttributeRequiredClusterHeight:
		return "FuncAttributeRequiredClusterHeight"
	case FuncAttributeRequiredClusterDepth:
		return "FuncAttributeRequiredClusterDepth"
	case FuncAttributeNonPortableClusterSizeAllowed:
		return "FuncAttributeNonPortableClusterSizeAllowed"
	case FuncAttributeClusterSchedulingPolicyPreference:
		return "FuncAttributeClusterSchedulingPolicyPreference"
	}
	return fmt.Sprintf("FunctionAttribute(%d)", e)
}

