// Limit Limits
type Limit uint32

const (
	LimitStackSize                    Limit = 0x00 // GPU thread stack size
	LimitPrintfFifoSize               Limit = 0x01 // GPU printf FIFO size
	LimitMallocHeapSize               Limit = 0x02 // GPU malloc heap size
	LimitDevRuntimeSyncDepth          Limit = 0x03 // GPU device runtime launch synchronize depth
	LimitDevRuntimePendingLaunchCount Limit = 0x04 // GPU device runtime pending launch count
	// LimitMaxL2FetchGranularity: A value between 0 and 128 that indicates the maximum fetch granularity of L2 (in Bytes). This is a hint
	LimitMaxL2FetchGranularity Limit = 0x05
	LimitPersistingL2CacheSize Limit = 0x06 // A size in bytes for L2 persisting lines cache size
	// LimitShmemSize: A maximum size in bytes of shared memory available to CUDA kernels on a CIG context. Can only be queried, cannot be set
	LimitShmemSize Limit = 0x07
	// LimitCigEnabled: A non-zero value indicates this CUDA context is a CIG-enabled context. Can only be queried, cannot be set
	LimitCigEnabled Limit = 0x08
	// LimitCigShmemFallbackEnabled: When set to zero, CUDA will fail to launch a kernel on a CIG context, instead of using the fallback path, if the kernel uses more shared memory than available
	LimitCigShmemFallbackEnabled Limit = 0x09
)

